1	import {
2	  AxisType,
3	  CartesianLayout,
4	  ChartOffsetInternal,
5	  RelativePointer,
6	  Coordinate,
7	  PolarCoordinate,
8	  PolarLayout,
9	  RangeObj,
10	  TickItem,
11	} from './types';
12	import { polarToCartesian } from './PolarUtils';
13	import { AxisRange } from '../state/selectors/axisSelectors';
14	import { mathSign } from './DataUtils';
15	
16	export const getActiveCartesianCoordinate = (
17	  layout: CartesianLayout,
18	  tooltipTicks: readonly TickItem[],
19	  activeIndex: number | undefined,
20	  pointer: RelativePointer,
21	): Coordinate => {
22	  const entry = tooltipTicks.find(tick => tick && tick.index === activeIndex);
23	
24	  if (entry) {
25	    if (layout === 'horizontal') {
26	      return { x: entry.coordinate, y: pointer.relativeY };
27	    }
28	    if (layout === 'vertical') {
29	      return { x: pointer.relativeX, y: entry.coordinate };
30	    }
31	  }
32	
33	  return { x: 0, y: 0 };
34	};
35	
36	/**
37	 * Get the active coordinate in polar coordinate system.
38	 * Internally we only really use x and y, but this returned object is part of public API
39	 * (because it goes straight to the tooltip content) so we keep all the other properties
40	 * for backwards compatibility.
41	 *
42	 * @param layout - The polar layout type ('centric' or 'radial').
43	 * @param tooltipTicks - Array of tick items used for tooltips.
44	 * @param activeIndex - The index of the active tick.
45	 * @param rangeObj - The range object containing polar chart properties.
46	 * @returns The active coordinate object with polar properties.
47	 */
48	export const getActivePolarCoordinate = (
49	  layout: PolarLayout,
50	  tooltipTicks: readonly TickItem[],
51	  activeIndex: number | undefined,
52	  rangeObj: RangeObj,
53	): PolarCoordinate => {
54	  const entry = tooltipTicks.find(tick => tick && tick.index === activeIndex);
55	
56	  if (entry) {
57	    if (layout === 'centric') {
58	      const angle = entry.coordinate;
59	      const { radius } = rangeObj;
60	
61	      return {
62	        ...rangeObj,
63	        ...polarToCartesian(rangeObj.cx, rangeObj.cy, radius, angle),
64	        angle,
65	        radius,
66	      };
67	    }
68	
69	    const radius = entry.coordinate;
70	    const { angle } = rangeObj;
71	
72	    return {
73	      ...rangeObj,
74	      ...polarToCartesian(rangeObj.cx, rangeObj.cy, radius, angle),
75	      angle,
76	      radius,
77	    };
78	  }
79	
80	  return {
81	    angle: 0,
82	    clockWise: false,
83	    cx: 0,
84	    cy: 0,
85	    endAngle: 0,
86	    innerRadius: 0,
87	    outerRadius: 0,
88	    radius: 0,
89	    startAngle: 0,
90	    x: 0,
91	    y: 0,
92	  };
93	};
94	
95	export function isInCartesianRange(pointer: RelativePointer, offset: ChartOffsetInternal): boolean {
96	  const { relativeX: x, relativeY: y } = pointer;
97	  return x >= offset.left && x <= offset.left + offset.width && y >= offset.top && y <= offset.top + offset.height;
98	}
99	
100	export const calculateActiveTickIndex = (
101	  /**
102	   * For different layouts, `coordinate` is different:
103	   * In horizontal layout, this is expected to be the `x` coordinate
104	   * vertical -> y
105	   * centric -> angle
106	   * radial -> radius
107	   */
108	  coordinate: number | undefined,
109	  ticks: ReadonlyArray<TickItem> | undefined,
110	  unsortedTicks: ReadonlyArray<TickItem>,
111	  axisType: AxisType | undefined,
112	  range: AxisRange | undefined,
113	): number | undefined => {
114	  const len = ticks?.length ?? 0;
115	
116	  // if there are 1 or fewer ticks or if there is no coordinate then the active tick is at index 0
117	  if (len <= 1 || coordinate == null) {
118	    return 0;
119	  }
120	
121	  if (axisType === 'angleAxis' && range != null && Math.abs(Math.abs(range[1] - range[0]) - 360) <= 1e-6) {
122	    // ticks are distributed in a circle
123	    for (let i = 0; i < len; i++) {
124	      const before = i > 0 ? unsortedTicks[i - 1]?.coordinate : unsortedTicks[len - 1]?.coordinate;
125	      const cur = unsortedTicks[i]?.coordinate;
126	      const after = i >= len - 1 ? unsortedTicks[0]?.coordinate : unsortedTicks[i + 1]?.coordinate;
127	      let sameDirectionCoord;
128	
129	      if (before == null || cur == null || after == null) {
130	        continue;
131	      }
132	
133	      if (mathSign(cur - before) !== mathSign(after - cur)) {
134	        const diffInterval = [];
135	        if (mathSign(after - cur) === mathSign(range[1] - range[0])) {
136	          sameDirectionCoord = after;
137	
138	          const curInRange = cur + range[1] - range[0];
139	          diffInterval[0] = Math.min(curInRange, (curInRange + before) / 2);
140	          diffInterval[1] = Math.max(curInRange, (curInRange + before) / 2);
141	        } else {
142	          sameDirectionCoord = before;
143	
144	          const afterInRange = after + range[1] - range[0];
145	          diffInterval[0] = Math.min(cur, (afterInRange + cur) / 2);
146	          diffInterval[1] = Math.max(cur, (afterInRange + cur) / 2);
147	        }
148	        const sameInterval: [number, number] = [
149	          Math.min(cur, (sameDirectionCoord + cur) / 2),
150	          Math.max(cur, (sameDirectionCoord + cur) / 2),
151	        ];
152	
153	        if (
154	          (coordinate > sameInterval[0] && coordinate <= sameInterval[1]) ||
155	          (coordinate >= diffInterval[0] && coordinate <= diffInterval[1])
156	        ) {
157	          return unsortedTicks[i]?.index;
158	        }
159	      } else {
160	        const minValue = Math.min(before, after);
161	        const maxValue = Math.max(before, after);
162	
163	        if (coordinate > (minValue + cur) / 2 && coordinate <= (maxValue + cur) / 2) {
164	          return unsortedTicks[i]?.index;
165	        }
166	      }
167	    }
168	  } else if (ticks) {
169	    // ticks are distributed in a single direction
170	    for (let i = 0; i < len; i++) {
171	      const curr = ticks[i];
172	      if (curr == null) {
173	        continue;
174	      }
175	      const next = ticks[i + 1];
176	      const prev = ticks[i - 1];
177	
178	      if (i === 0 && next != null && coordinate <= (curr.coordinate + next.coordinate) / 2) {
179	        return curr.index;
180	      }
181	
182	      if (i === len - 1 && prev != null && coordinate > (curr.coordinate + prev.coordinate) / 2) {
183	        return curr.index;
184	      }
185	
186	      if (
187	        i > 0 &&
188	        i < len - 1 &&
189	        prev != null &&
190	        next != null &&
191	        coordinate > (curr.coordinate + prev.coordinate) / 2 &&
192	        coordinate <= (curr.coordinate + next.coordinate) / 2
193	      ) {
194	        return curr.index;
195	      }
196	    }
197	  }
198	
199	  return -1;
