315	/**
316	 * Calculate the coordinate of line endpoint
317	 * @param data The data if there are ticks
318	 * @param props axis settings
319	 * @return (x1, y1): The point close to text,
320	 *         (x2, y2): The point close to axis
321	 */
322	const getTickLineCoord = (
323	  data: TickItem,
324	  props: InternalPolarAngleAxisProps,
325	): {
326	  x1: number;
327	  y1: number;
328	  x2: number;
329	  y2: number;
330	} => {
331	  const { cx, cy, radius, orientation, tickSize } = props;
332	  const tickLineSize = tickSize || 8;
333	  const p1 = polarToCartesian(cx, cy, radius, data.coordinate);
334	  const p2 = polarToCartesian(cx, cy, radius + (orientation === 'inner' ? -1 : 1) * tickLineSize, data.coordinate);
335	
336	  return { x1: p1.x, y1: p1.y, x2: p2.x, y2: p2.y };
