332	  const tickLineSize = tickSize || 8;
333	  const p1 = polarToCartesian(cx, cy, radius, data.coordinate);
334	  const p2 = polarToCartesian(cx, cy, radius + (orientation === 'inner' ? -1 : 1) * tickLineSize, data.coordinate);
335	
336	  return { x1: p1.x, y1: p1.y, x2: p2.x, y2: p2.y };
337	};
338	
339	/**
340	 * Get the text-anchor of each tick
341	 * @param data Data of ticks
342	 * @param orientation of the axis ticks
343	 * @return text-anchor
344	 */
345	const getTickTextAnchor = (data: TickItem, orientation: Props['orientation']): TextAnchor => {
346	  const cos = Math.cos(degreeToRadian(-data.coordinate));
347	
348	  if (cos > eps) {
349	    return orientation === 'outer' ? 'start' : 'end';
350	  }
351	  if (cos < -eps) {
352	    return orientation === 'outer' ? 'end' : 'start';
353	  }
354	  return 'middle';
355	};
356	
357	/**
358	 * Get the text vertical anchor of each tick
359	 * @param data Data of a tick
360	 * @return text vertical anchor
361	 */
362	const getTickTextVerticalAnchor = (data: TickItem): TextVerticalAnchor => {
363	  const cos = Math.cos(degreeToRadian(-data.coordinate));
364	  const sin = Math.sin(degreeToRadian(-data.coordinate));
365	
366	  // handle top and bottom sectors: 90±45deg and 270±45deg
367	  if (Math.abs(cos) <= COS_45) {
368	    // sin > 0: top sector, sin < 0: bottom sector
369	    return sin > 0 ? 'start' : 'end';
370	  }
371	
372	  return 'middle';
373	};
374	
375	const AxisLine = (props: InternalPolarAngleAxisProps) => {
376	  const { cx, cy, radius, axisLineType, axisLine, ticks } = props;
377	  if (!axisLine) {
378	    return null;
379	  }
380	  const axisLineProps = {
381	    ...svgPropertiesNoEvents(props),
382	    fill: 'none',
383	    ...svgPropertiesNoEvents(axisLine),
384	  };
385	
386	  if (axisLineType === 'circle') {
387	    // @ts-expect-error wrong SVG element type
388	    return <Dot className="recharts-polar-angle-axis-line" {...axisLineProps} cx={cx} cy={cy} r={radius} />;
389	  }
390	  const points = ticks.map(entry => polarToCartesian(cx, cy, radius, entry.coordinate));
391	
392	  // @ts-expect-error wrong SVG element type
393	  return <Polygon className="recharts-polar-angle-axis-line" {...axisLineProps} points={points} />;
394	};
395	
396	type TickItemProps = {
397	  tick: TickProp<BaseTickContentProps>;
398	  tickProps: BaseTickContentProps;
399	  value: string | number;
400	};
401	
402	const TickItemText = ({ tick, tickProps, value }: TickItemProps): ReactNode => {
403	  if (!tick) {
404	    return null;
405	  }
406	  if (React.isValidElement(tick)) {
407	    return React.cloneElement(tick, tickProps);
408	  }
409	  if (typeof tick === 'function') {
410	    return tick(tickProps);
411	  }
412	  return (
413	    <Text {...tickProps} className="recharts-polar-angle-axis-tick-value">
414	      {value}
415	    </Text>
416	  );
417	};
418	
419	const Ticks = (props: InternalPolarAngleAxisProps) => {
420	  const { tick, tickLine, tickFormatter, stroke, ticks } = props;
421	  const { ref, ...axisProps } = svgPropertiesNoEvents(props);
422	  const customTickProps = svgPropertiesNoEventsFromUnknown(tick);
423	  const tickLineProps = {
424	    ...axisProps,
425	    fill: 'none',
426	    ...svgPropertiesNoEvents(tickLine),
427	  };
428	
429	  const items = ticks.map((entry, i) => {
430	    const lineCoord = getTickLineCoord(entry, props);
431	    const textAnchor: TextAnchor = getTickTextAnchor(entry, props.orientation);
432	    const verticalAnchor: TextVerticalAnchor = getTickTextVerticalAnchor(entry);
433	    const tickProps: BaseTickContentProps = {
434	      ...axisProps,
435	      // @ts-expect-error customTickProps is contributing unknown props
436	      textAnchor,
437	      verticalAnchor,
438	      // @ts-expect-error customTickProps is contributing unknown props
439	      stroke: 'none',
440	      // @ts-expect-error customTickProps is contributing unknown props
441	      fill: stroke,
442	      ...customTickProps,
443	      index: i,
444	      payload: entry,
445	      x: lineCoord.x2,
446	      y: lineCoord.y2,
447	    };
448	
449	    return (
450	      <Layer
451	        className={clsx('recharts-polar-angle-axis-tick', getClassNameFromUnknown(tick))}
452	        key={`tick-${entry.coordinate}`}
453	        {...adaptEventsOfChild(props, entry, i)}
454	      >
455	        {tickLine && <line className="recharts-polar-angle-axis-tick-line" {...tickLineProps} {...lineCoord} />}
456	        <TickItemText
457	          tick={tick}
458	          tickProps={tickProps}
459	          value={tickFormatter ? tickFormatter(entry.value, i) : entry.value}
460	        />
461	      </Layer>
462	    );
463	  });
464	
465	  return <Layer className="recharts-polar-angle-axis-ticks">{items}</Layer>;
466	};
467	
468	export const PolarAngleAxisWrapper: FunctionComponent<PropsWithDefaults> = (defaultsAndInputs: PropsWithDefaults) => {
469	  const { angleAxisId } = defaultsAndInputs;
470	
471	  const viewBox = useAppSelector(selectPolarViewBox);
472	  const scale = useAppSelector(state => selectPolarAxisScale(state, 'angleAxis', angleAxisId));
473	  const isPanorama = useIsPanorama();
474	  const ticks = useAppSelector(state => selectPolarAngleAxisTicks(state, 'angleAxis', angleAxisId, isPanorama));
475	
476	  if (viewBox == null || !ticks || !ticks.length || scale == null) {
477	    return null;
478	  }
479	
480	  const props: InternalPolarAngleAxisProps = {
481	    ...defaultsAndInputs,
482	    scale,
483	    ...viewBox,
484	    radius: viewBox.outerRadius,
485	    ticks,
486	  };
487	
488	  return (
489	    <ZIndexLayer zIndex={props.zIndex}>
490	      <Layer className={clsx('recharts-polar-angle-axis', AXIS_TYPE, props.className)}>
491	        <AxisLine {...props} />
492	        <Ticks {...props} />
493	      </Layer>
494	    </ZIndexLayer>
495	  );
496	};
497	
498	/**
499	 * @provides PolarLabelContext
500	 * @consumes PolarViewBoxContext
501	 */
502	export function PolarAngleAxis<DataPointType = any, DataValueType = any>(
503	  outsideProps: Props<DataPointType, DataValueType>,
504	): React.ReactNode {
505	  const props: PropsWithDefaults<DataPointType, DataValueType> = resolveDefaultProps(
506	    outsideProps,
507	    defaultPolarAngleAxisProps,
508	  );
509	
510	  return (
511	    <SetAngleAxisSettings
512	      id={props.angleAxisId}
513	      scale={props.scale}
514	      type={props.type}
515	      dataKey={props.dataKey}
516	      unit={undefined}
517	      name={props.name}
518	      allowDuplicatedCategory={false} // Ignoring the prop on purpose because axis calculation behaves as if it was false and Tooltip requires it to be true.
519	      allowDataOverflow={false}
520	      reversed={props.reversed}
521	      includeHidden={false}
522	      allowDecimals={props.allowDecimals}
523	      tickCount={props.tickCount}
524	      niceTicks={props.niceTicks ?? 'auto'}
525	      // @ts-expect-error the type does not match. Is RadiusAxis really expecting what it says?
526	      ticks={props.ticks}
527	      tick={props.tick}
528	      domain={props.domain}
529	    >
530	      <PolarAngleAxisWrapper {...props} />
531	    </SetAngleAxisSettings>
532	  );
533	}
534	
535	PolarAngleAxis.displayName = 'PolarAngleAxis';
536

