import React from 'react';
import { describe, expect, it } from 'vitest';
import { render } from '@testing-library/react';
import { RadarChart, Radar, PolarAngleAxis, Tooltip } from '../../src';

const data = [
  { name: 'North', score: 100 },
  { name: 'East', score: 25 },
  { name: 'South', score: 75 },
  { name: 'West', score: 50 },
];

describe('repro', () => {
  it('renders and prints polygon + tick text + tick lines', () => {
    const { container } = render(
      <RadarChart cx={300} cy={300} outerRadius={200} width={600} height={600} data={data}>
        <PolarAngleAxis dataKey="name" />
        <Radar dataKey="score" />
        <Tooltip />
      </RadarChart>,
    );
    const polygon = container.querySelector('.recharts-radar-polygon');
    console.log('POLYGON POINTS', polygon?.getAttribute('points'));

    const ticks = container.querySelectorAll('.recharts-polar-angle-axis-tick-value');
    ticks.forEach(t => console.log('TICK TEXT', t.textContent, t.getAttribute('x'), t.getAttribute('y')));

    const dots = container.querySelectorAll('.recharts-radar-dot');
    dots.forEach(d => console.log('DOT', d.getAttribute('cx'), d.getAttribute('cy')));
  });
});
EOF
