import React from 'react';
import { describe, expect, it } from 'vitest';
import { RadarChart, Radar, PolarAngleAxis } from '../../src';
import { createSelectorTestCase } from '../helper/createSelectorTestCase';
import { selectPolarAngleAxisTicks, selectPolarAxisScale } from '../../src/state/selectors/polarScaleSelectors';

const data = [
  { name: 'North', score: 100 },
  { name: 'East', score: 25 },
  { name: 'South', score: 75 },
  { name: 'West', score: 50 },
];

describe('repro', () => {
  const renderTestCase = createSelectorTestCase(({ children }) => (
    <RadarChart cx={300} cy={300} outerRadius={200} width={600} height={600} data={data}>
      <PolarAngleAxis dataKey="name" />
      <Radar dataKey="score" />
      {children}
    </RadarChart>
  ));

  it('compares raw scale.map (used to draw) vs label ticks (used to render axis text)', () => {
    const { spy: scaleSpy } = renderTestCase(state => selectPolarAxisScale(state, 'angleAxis', 0));
    const scale = scaleSpy.mock.results[scaleSpy.mock.results.length - 1].value;
    data.forEach(d => {
      console.log('RAW ANGLE for', d.name, '=', scale.map(d.name));
    });

    const { spy: tickSpy } = renderTestCase(state => selectPolarAngleAxisTicks(state, 'angleAxis', 0, false));
    const ticks = tickSpy.mock.results[tickSpy.mock.results.length - 1].value;
    ticks.forEach(t => console.log('LABEL ANGLE for', t.value, '=', t.coordinate));
  });
});
EOF
