import React from 'react';
import { describe, expect, it } from 'vitest';
import { RadarChart, Radar, PolarAngleAxis } from '../../src';
import { createSelectorTestCase } from '../helper/createSelectorTestCase';
import {
  selectPolarAngleAxisTicks,
  selectPolarAxisScale,
  selectPolarAxisTicks,
  selectPolarGraphicalItemAxisTicks,
} from '../../src/state/selectors/polarScaleSelectors';
import { selectAngleAxisRangeWithReversed } from '../../src/state/selectors/polarAxisSelectors';
import { selectRealScaleType } from '../../src/state/selectors/axisSelectors';

const data = [
  { name: 'North', score: 100 },
  { name: 'East', score: 25 },
  { name: 'South', score: 75 },
  { name: 'West', score: 50 },
];

describe('repro', () => {
  const renderTestCase = createSelectorTestCase(({ children }) => (
    <RadarChart cx={300} cy={300} outerRadius={200} width={600} height={600} data={data}>
      <PolarAngleAxis dataKey="name" />
      <Radar dataKey="score" />
      {children}
    </RadarChart>
  ));

  it('dumps everything', () => {
    const { spy: rangeSpy } = renderTestCase(state => selectAngleAxisRangeWithReversed(state, 0));
    console.log('RANGE', JSON.stringify(rangeSpy.mock.calls.at(-1)?.[0]));

    const { spy: realScaleSpy } = renderTestCase(state => selectRealScaleType(state, 'angleAxis', 0));
    console.log('REAL SCALE TYPE', realScaleSpy.mock.calls.at(-1)?.[0]);

    const { spy: axisTicksSpy } = renderTestCase(state => selectPolarAxisTicks(state, 'angleAxis', 0, false));
    console.log('AXIS TICKS (combineAxisTicks)', JSON.stringify(axisTicksSpy.mock.calls.at(-1)?.[0]));

    const { spy: giTicksSpy } = renderTestCase(state => selectPolarGraphicalItemAxisTicks(state, 'angleAxis', 0, false));
    console.log('GRAPHICAL ITEM TICKS', JSON.stringify(giTicksSpy.mock.calls.at(-1)?.[0]));

    const { spy: labelTicksSpy } = renderTestCase(state => selectPolarAngleAxisTicks(state, 'angleAxis', 0, false));
    console.log('LABEL TICKS (dedup)', JSON.stringify(labelTicksSpy.mock.calls.at(-1)?.[0]));
  });
});
EOF
