import React from 'react';
import { describe, expect, it } from 'vitest';
import { RadarChart, Radar, PolarAngleAxis, PolarRadiusAxis } from '../../src';

const data = [
  { name: 'North', score: 100 },
  { name: 'East', score: 25 },
  { name: 'South', score: 75 },
  { name: 'West', score: 50 },
];

describe('repro reversed direction', () => {
  it('renders with increasing angle direction (startAngle < endAngle)', () => {
    const { container } = render_(-270, 90);
    printAll(container);
  });
  it('renders with default decreasing angle direction (startAngle > endAngle)', () => {
    const { container } = render_(90, -270);
    printAll(container);
  });
});

function render_(startAngle: number, endAngle: number) {
  const { render } = require('@testing-library/react');
  return render(
    <RadarChart
      cx={300}
      cy={300}
      outerRadius={200}
      width={600}
      height={600}
      data={data}
      startAngle={startAngle}
      endAngle={endAngle}
    >
      <PolarAngleAxis dataKey="name" />
      <PolarRadiusAxis domain={[0, 100]} />
      <Radar dataKey="score" isAnimationActive={false} />
    </RadarChart>,
  );
}

function printAll(container: HTMLElement) {
  const polygon = container.querySelector('.recharts-radar-polygon path');
