import React from 'react';
import { render } from '@testing-library/react';
import { describe, expect, it } from 'vitest';
import { RadarChart, Radar, PolarAngleAxis, PolarRadiusAxis, Tooltip } from '../../src';
import { showTooltipOnCoordinate, getTooltip } from '../component/Tooltip/tooltipTestHelpers';
import { mockGetBoundingClientRect } from '../helper/mockGetBoundingClientRect';

const data = [
  { name: 'North', score: 100 },
  { name: 'East', score: 25 },
  { name: 'South', score: 75 },
  { name: 'West', score: 50 },
];

describe('sweep hover around circle, default direction', () => {
  it('sweeps 24 angles and prints resolved tooltip', () => {
    mockGetBoundingClientRect({ width: 600, height: 600, x: 0, y: 0, top: 0, left: 0 });
    const { container } = render(
      <RadarChart cx={300} cy={300} outerRadius={200} width={600} height={600} data={data}>
        <PolarAngleAxis dataKey="name" />
        <PolarRadiusAxis domain={[0, 100]} />
        <Radar dataKey="score" isAnimationActive={false} />
        <Tooltip />
      </RadarChart>,
    );
    for (let deg = 0; deg < 360; deg += 15) {
      const rad = (deg * Math.PI) / 180;
      // screen angle: 0 deg = East(right), increasing clockwise visually but let's just use standard screen coords
      const x = 300 + Math.cos(rad) * 150;
      const y = 300 - Math.sin(rad) * 150; // recharts uses y-flipped (angle measured counterclockwise like math, but screen y down)
      showTooltipOnCoordinate(container, '.recharts-wrapper', { clientX: x, clientY: y });
      const tooltip = getTooltip(container);
      console.log(`screenDeg=${deg} pos=(${x.toFixed(0)},${y.toFixed(0)}) => ${tooltip.textContent}`);
    }
  });
});
EOF
