import React from 'react';
import { render } from '@testing-library/react';
import { describe, expect, it } from 'vitest';
import { RadarChart, Radar, PolarAngleAxis, PolarRadiusAxis, Tooltip } from '../../src';
import { showTooltipOnCoordinate, getTooltip } from '../component/Tooltip/tooltipTestHelpers';
import { mockGetBoundingClientRect } from '../helper/mockGetBoundingClientRect';

const data = [
  { name: 'North', score: 100 },
  { name: 'East', score: 25 },
  { name: 'South', score: 75 },
  { name: 'West', score: 50 },
];

describe('startAngle=0 endAngle=360 (increasing direction) full repro', () => {
  it('polygon vs labels vs hover, all should agree but do not', () => {
    mockGetBoundingClientRect({ width: 600, height: 600, x: 0, y: 0, top: 0, left: 0 });
    const { container } = render(
      <RadarChart cx={300} cy={300} outerRadius={200} width={600} height={600} data={data} startAngle={0} endAngle={360}>
        <PolarAngleAxis dataKey="name" />
        <PolarRadiusAxis domain={[0, 100]} />
        <Radar dataKey="score" isAnimationActive={false} />
        <Tooltip />
      </RadarChart>,
    );
    const polygon = container.querySelector('.recharts-radar-polygon path');
    console.log('POLYGON', polygon?.getAttribute('d'));
    const ticks = container.querySelectorAll('.recharts-polar-angle-axis-tick-value');
    ticks.forEach(t => console.log('TICK', t.textContent, t.getAttribute('x'), t.getAttribute('y')));

    for (let deg = 0; deg < 360; deg += 45) {
      const rad = (deg * Math.PI) / 180;
      const x = 300 + Math.cos(rad) * 150;
      const y = 300 - Math.sin(rad) * 150;
      showTooltipOnCoordinate(container, '.recharts-wrapper', { clientX: x, clientY: y });
      const tooltip = getTooltip(container);
      console.log(`  hover deg=${deg} pos=(${x.toFixed(0)},${y.toFixed(0)}) => ${tooltip.textContent}`);
    }
  });
});
EOF
