import { describe, expect, it } from 'vitest';
import { RadarChart, PolarAngleAxis, Radar, PolarRadiusAxis } from '../../src';
import { useAppSelector } from '../../src/state/hooks';
import { selectRadarPoints } from '../../src/state/selectors/radarSelectors';
import { selectPolarAngleAxisTicks, selectPolarAxisScale } from '../../src/state/selectors/polarScaleSelectors';
import { selectUnfilteredPolarItems } from '../../src/state/selectors/polarSelectors';

const data = [
  { name: 'North', score: 100 },
  { name: 'East', score: 25 },
  { name: 'South', score: 75 },
  { name: 'West', score: 50 },
];

function Probe() {
  const items = useAppSelector(state => selectUnfilteredPolarItems(state));
  console.log('ITEMS', JSON.stringify(items));
  const radarId = items?.find((i: any) => i.type === 'radar')?.id;
  const points = useAppSelector(state => selectRadarPoints(state, 0, 0, false, radarId));
  console.log('POINTS', JSON.stringify(points?.points?.map((p: any) => ({ name: p.name, angle: p.angle }))));
  return null;
}

describe('point angle vs label angle, default', () => {
  it('dumps', () => {
    render(
      <RadarChart cx={300} cy={300} outerRadius={200} width={600} height={600} data={data}>
        <PolarAngleAxis dataKey="name" />
        <PolarRadiusAxis domain={[0, 100]} />
        <Radar dataKey="score" />
        <Probe />
      </RadarChart>,
    );
  });
});
EOF
npx vitest run test/chart/repro.spec.tsx --reporter=verbose 2>&1 | grep -E "ITEMS|POINTS"

