import React from 'react';
import { describe, expect, it } from 'vitest';
import { RadarChart, PolarAngleAxis, Radar } from '../../src';
import { createSelectorTestCase } from '../helper/createSelectorTestCase';
import { selectPolarAngleAxisTicks } from '../../src/state/selectors/polarScaleSelectors';

const data = [
  { name: 'North', score: 100 },
  { name: 'East', score: 25 },
  { name: 'South', score: 75 },
  { name: 'West', score: 50 },
];

describe('offset dump', () => {
  const renderTestCase = createSelectorTestCase(({ children }) => (
    <RadarChart cx={300} cy={300} outerRadius={200} width={600} height={600} data={data}>
      <PolarAngleAxis dataKey="name" />
      <Radar dataKey="score" />
      {children}
