77	export function createSelectorTestCase(Component: ComponentType<{ children: ReactNode }>) {
78	  return function renderTestCase<T>(
79	    selector: ReactHook<T> | Selector<RechartsRootState, T, never> | undefined = undefined,
80	  ): TestCaseResult<T> {
