194	 * Useful for testing synchronisation!
195	 *
196	 * @param ComponentA first component to render
197	 * @param ComponentB second component to render
198	 * @param ComponentC optional third component to render
199	 * @returns a function that renders the test case
200	 */
201	export function createSynchronisedSelectorTestCase(
202	  ComponentA: ComponentType<{ children: ReactNode }>,
203	  ComponentB: ComponentType<{ children: ReactNode }>,
204	  ComponentC?: ComponentType<{ children: ReactNode }>,
205	) {
206	  return function renderTestCase<T>(selector: Selector<RechartsRootState, T | undefined, never> = emptySelector): {
207	    container: Element;
208	    wrapperA: Element;
209	    wrapperB: Element;
210	    wrapperC: Element | null;
211	    spyA: Mock<(selectorResult: T) => void>;
212	    spyB: Mock<(selectorResult: T) => void>;
213	    spyC: Mock<(selectorResult: T) => void>;
214	    debug: () => void;
215	  } {
216	    /*
217	     * Some of our tests are calling createSelectorTestCase twice in one test, with the assumption that they are independent.
218	     * Well guess what, testing-library/react renders are not independent. In fact, they append to the same DOM.
219	     * Which I find surprising, and I wasn't alone, so let's call cleanup here
220	     * to continue pretending that they are indeed independent.
221	     */
