import React from 'react';
import { describe, it } from 'vitest';
import { RadarChart, Radar, PolarAngleAxis, PolarRadiusAxis, Tooltip } from '../../src';
import { createSelectorTestCase } from '../helper/createSelectorTestCase';
import { selectPolarAngleAxisTicks, selectPolarAxisScale } from '../../src/state/selectors/polarScaleSelectors';
import { selectRadarPoints } from '../../src/state/selectors/radarSelectors';

const data = [
  { name: 'North', score: 100 },
  { name: 'East', score: 25 },
  { name: 'South', score: 75 },
  { name: 'West', score: 50 },
];

function makeComponent(startAngle: number, endAngle: number) {
  return function Comp({ children }: { children: React.ReactNode }) {
    return (
      <RadarChart
        cx={300}
        cy={300}
        outerRadius={200}
        width={600}
        height={600}
        data={data}
        startAngle={startAngle}
        endAngle={endAngle}
      >
        <PolarAngleAxis dataKey="name" />
        <PolarRadiusAxis domain={[0, 100]} />
        <Radar dataKey="score" isAnimationActive={false} />
        <Tooltip />
        {children}
      </RadarChart>
    );
  };
}

describe('tick offset investigation', () => {
  it.each([
    [90, -270],
    [0, 360],
    [-270, 90],
    [360, 0],
  ])('startAngle=%d endAngle=%d', (startAngle, endAngle) => {
    const renderTestCase = createSelectorTestCase(makeComponent(startAngle, endAngle));
    const { spy } = renderTestCase(state => {
      const ticks = selectPolarAngleAxisTicks(state, 0, false);
      const scale = selectPolarAxisScale(state, 'angleAxis', 0);
      const radarPoints = selectRadarPoints(state, 0, 0, false, 0);
      return { ticks, rawMap: data.map(d => [d.name, scale?.map(d.name)]), radarPoints: radarPoints?.points };
    });
    console.log(`===== ${startAngle}/${endAngle}`);
    console.log('TICKS', JSON.stringify(spy.mock.calls.at(-1)?.[0]?.ticks));
    console.log('RAW MAP', JSON.stringify(spy.mock.calls.at(-1)?.[0]?.rawMap));
    console.log(
      'RADAR POINTS',
      JSON.stringify(spy.mock.calls.at(-1)?.[0]?.radarPoints?.map((p: any) => ({ name: p.name, angle: p.angle }))),
    );
  });
});

