import React from 'react';
import { describe, it } from 'vitest';
import { RadarChart, Radar, PolarAngleAxis, PolarRadiusAxis, Tooltip } from '../../src';
import { createSelectorTestCase } from '../helper/createSelectorTestCase';
import { selectPolarAngleAxisTicks } from '../../src/state/selectors/polarScaleSelectors';
import { selectRadarPoints } from '../../src/state/selectors/radarSelectors';

const data = [
  { name: 'North', score: 100 },
  { name: 'East', score: 25 },
  { name: 'South', score: 75 },
  { name: 'West', score: 50 },
];

function makeComponent(startAngle: number, endAngle: number) {
  return function Comp({ children }: { children: React.ReactNode }) {
    return (
      <RadarChart
        cx={300}
        cy={300}
        outerRadius={200}
        width={600}
        height={600}
        data={data}
        startAngle={startAngle}
        endAngle={endAngle}
      >
        <PolarAngleAxis dataKey="name" />
        <PolarRadiusAxis domain={[0, 100]} />
        <Radar dataKey="score" isAnimationActive={false} />
        <Tooltip />
        {children}
      </RadarChart>
    );
  };
}

describe('tick vs radar point consistency', () => {
  it.each([
    [90, -270],
    [0, 360],
    [-270, 90],
    [360, 0],
    [45, 405],
    [-90, 270],
    [270, -90],
  ])('startAngle=%d endAngle=%d', (startAngle, endAngle) => {
    const renderTestCase = createSelectorTestCase(makeComponent(startAngle, endAngle));
    const { spy } = renderTestCase(state => selectPolarAngleAxisTicks(state, 'angleAxis', 0, false));
    const ticks = spy.mock.calls.at(-1)?.[0];

    const renderTestCase3 = createSelectorTestCase(makeComponent(startAngle, endAngle));
    const { spy: spy3 } = renderTestCase3(state => selectRadarPoints(state, 0, 0, false, 0));
    const radarPoints = spy3.mock.calls.at(-1)?.[0];

    console.log(`===== ${startAngle}/${endAngle}`);
    console.log('TICKS', JSON.stringify(ticks?.map((t: any) => [t.value, t.coordinate])));
    console.log(
      'RADAR POINTS',
      JSON.stringify(radarPoints?.points?.map((p: any) => [p.name, ((p.angle % 360) + 360) % 360])),
    );

    const tickMap = new Map(ticks?.map((t: any) => [t.value, ((t.coordinate % 360) + 360) % 360]));
    radarPoints?.points?.forEach((p: any) => {
      const tickAngle = tickMap.get(p.name);
      const pointAngle = ((p.angle % 360) + 360) % 360;
      const diff = Math.abs(tickAngle - pointAngle);
      const wrapped = Math.min(diff, 360 - diff);
      if (wrapped > 1e-6) {
        console.log(`MISMATCH for ${p.name}: tick=${tickAngle} point=${pointAngle}`);
      }
    });
  });
});

