  describe('full-circle self-consistency', () => {
    /*
     * Regression test for a bug where the angle axis tick labels (and by extension, the tooltip
     * hover resolution, which reads from the same tick set) disagreed with the angles of the
     * points making up the drawn Radar polygon, whenever the chart's angle axis range increased
     * (e.g. startAngle=0, endAngle=360) rather than decreased (the RadarChart default,
     * startAngle=90, endAngle=-270). See https://github.com/recharts/recharts - "Full-circle polar
     * chart is inconsistent with its own axis".
     */
    const data = [
      { name: 'North', score: 100 },
      { name: 'East', score: 25 },
      { name: 'South', score: 75 },
      { name: 'West', score: 50 },
    ];

    function makeComponent(startAngle: number, endAngle: number) {
      return function Comp({ children }: { children: React.ReactNode }) {
        return (
          <RadarChart
            cx={300}
            cy={300}
            outerRadius={200}
            width={600}
            height={600}
            data={data}
            startAngle={startAngle}
            endAngle={endAngle}
          >
            <PolarAngleAxis dataKey="name" />
            <PolarRadiusAxis domain={[0, 100]} />
            <Radar id="radar1" dataKey="score" isAnimationActive={false} />
            <Tooltip />
            {children}
          </RadarChart>
        );
      };
    }

    function normalizeAngle(angle: number): number {
      return ((angle % 360) + 360) % 360;
    }

    it.each([
      [90, -270], // RadarChart default: decreasing direction
      [0, 360], // increasing direction - this used to be broken
      [-270, 90],
      [360, 0],
      [45, 405],
      [-90, 270],
      [270, -90],
    ])(
      'the drawn polygon vertex for each series matches its own axis tick, for startAngle=%d endAngle=%d',
      (startAngle, endAngle) => {
        const renderTestCaseTicks = createSelectorTestCase(makeComponent(startAngle, endAngle));
        const { spy: ticksSpy } = renderTestCaseTicks(state => selectPolarAngleAxisTicks(state, 'angleAxis', 0, false));
        const ticks = ticksSpy.mock.calls.at(-1)?.[0];
        assertNotNull(ticks);
        const tickAngleByName = new Map(ticks.map(tick => [tick.value, normalizeAngle(tick.coordinate)]));

        const renderTestCasePoints = createSelectorTestCase(makeComponent(startAngle, endAngle));
        const { spy: pointsSpy } = renderTestCasePoints(state => selectRadarPoints(state, 0, 0, false, 'radar1'));
        const radarPoints = pointsSpy.mock.calls.at(-1)?.[0];
        assertNotNull(radarPoints);

        expect(radarPoints.points).toHaveLength(data.length);
        radarPoints.points.forEach(point => {
          const tickAngle = tickAngleByName.get(point.name);
          expect(tickAngle).toBeDefined();
          expect(normalizeAngle(point.angle)).toBeCloseTo(tickAngle as number, 6);
        });
      },
    );

    it('hovering near a spoke resolves the tooltip to that spoke\'s own series, for a chart whose angle axis increases (startAngle=0, endAngle=360)', () => {
      mockGetBoundingClientRect({ width: 600, height: 600, top: 0, left: 0 });
      const Comp = makeComponent(0, 360);
      const { container } = render(<Comp>{null}</Comp>);

      /*
       * With startAngle=0, endAngle=360, North's tick coordinate is -90 degrees, which
       * polarToCartesian maps to the BOTTOM of the chart (cy + outerRadius), not the top.
       * Hovering there must resolve to North - matching both its axis label and its drawn point.
       */
      showTooltipOnCoordinate(container, '.recharts-surface', { clientX: 300, clientY: 450 });
      const tooltip = getTooltip(container);
      expect(tooltip.textContent).toContain('North');
      expect(tooltip.textContent).toContain('100');
    });
  });
});

